  "root_cause": "Arrow key navigation in Pikaday does not respect the disableDayFn callback, allowing movement onto disabled weekend days.",
  "repair_strategy": "Modify the adjustDate method to repeatedly add or subtract one day until the resulting date is not disabled by disableDayFn, while respecting min/max bounds and using a safety iteration limit.",
  "edits": [
    {
      "path": "pikaday.js",
      "sha256": "a50b66482ec18884a7200882e9b523d9192b224b40b296cdd4080530f114fa75",
      "before": "        adjustDate: function(sign, days) {

            var day = this.getDate() || new Date();
            var difference = parseInt(days)*24*60*60*1000;

            var newDay;

            if (sign === 'add') {
                newDay = new Date(day.valueOf() + difference);
            } else if (sign === 'subtract') {
                newDay = new Date(day.valueOf() - difference);
            }

            this.setDate(newDay);
        },",
      "after": "        adjustDate: function(sign, days) {

            var day = this.getDate() || new Date();
            var difference = parseInt(days)*24*60*60*1000;

            var newDay;

            if (sign === 'add') {
                newDay = new Date(day.valueOf() + difference);
            } else if (sign === 'subtract') {
                newDay = new Date(day.valueOf() - difference);
            }

            // Skip disabled days
            if (this._o.disableDayFn && typeof this._o.disableDayFn === 'function') {
                var limit = 1000; // safety
                while (limit--) {
                    if (!this._o.disableDayFn(newDay)) {
                        break;
                    }
                    if (sign === 'add') {
                        newDay = new Date(newDay.valueOf() + 24*60*60*1000);
                    } else {
                        newDay = new Date(newDay.valueOf() - 24*60*60*1000);
                    }
                    // Respect min/max
                    var min = this._o.minDate,
                        max = this._o.maxDate;
                    if (min && newDay < min) {
                        newDay = min;
                        break;
                    }
                    if (max && newDay > max) {
                        newDay = max;
                        break;
                    }
                }
            }

            this.setDate(newDay);
        },"
    }
  ],
  "expected_accessibility_effect": "ArrowRight will now skip weekends, moving from Friday to the next Monday, satisfying WCAG 2.1.1 keyboard accessibility for date selection.",
  "functional_risks": [
    "Potential infinite loop if disableDayFn always returns true and min/max do not bound the search; mitigated by iteration limit and boundary checks.",
    "Performance impact if large date ranges are traversed, but limited by the safety cap of 1000 iterations.",
    "Ensure that min/max constraints still take precedence over disableDayFn skipping."
  ],
  "verification_requirements": [
    "Verify that ArrowRight from Friday 2026-11-20 results in 2026-11-23 (Monday).",
    "Verify that ArrowLeft from Monday 2026-11-23 results in 2026-11-20 (Friday).",
    "Confirm that minDate and maxDate constraints still prevent navigation beyond those bounds.",
    "Ensure that dates marked disabled by disableDayFn cannot be selected via mouse or keyboard."
  ]
}

